const raw = $input.first().json.content[0].text;
const start = raw.indexOf('{'), end = raw.lastIndexOf('}');
let r;
try { r = JSON.parse(raw.slice(start, end + 1)); }
catch (e) { r = { candidate_name: 'PARSE_ERROR', match_score: 0, recommendation: 'maybe', matched_skills: [], missing_skills: [], summary: raw.slice(0, 200) }; }
const hook = $('Webhook').first().json.body;
return [{ json: {
  timestamp: new Date().toISOString(),
  candidate_email: hook.candidate_email || '',
  candidate_name: r.candidate_name,
  match_score: r.match_score,
  recommendation: r.recommendation,
  matched_skills: (r.matched_skills || []).join(', '),
  missing_skills: (r.missing_skills || []).join(', '),
  summary: r.summary
}}];
